<template>
  <main class="assessment-view" :class="{ 'is-wrong': wrongFlash }" :style="{ '--timer-danger-pulse': `${visual.timerDangerPulseSeconds}s`, '--combo-reveal': `${visual.comboRevealMs}ms`, '--seal-duration': `${visual.seal.durationMs}ms`, '--paper-texture-opacity': visual.paper.textureOpacity }">
    <header class="assessment-head">
      <p>第{{ store.gateIndex + 1 }}关 · {{ nodeLabel }} · 过关试炼</p>
      <button title="退出考核" @click="requestExit">x</button>
    </header>
    <section v-if="store.phase === 'loading'" class="state-copy">小岐正在铺开试卷…</section>
    <section v-else-if="store.phase === 'result' && store.result" class="result-stage">
      <div class="score-wrap"><p>综合分</p><strong>{{ scoreDisplay }}</strong><i>/ 100</i><span class="threshold" :style="{ bottom: `${store.result.threshold}%` }">达标 {{ store.result.threshold }}</span></div>
      <template v-if="store.result.passed"><div ref="seal" class="pass-seal">过</div><img class="mascot celebrate" :src="xiaoqi" alt="小岐庆祝"/><h1>榜上有名</h1><p>这一关已刻入脉络，气血将向下一节点流转。</p><button class="primary" @click="returnToMap">返回脉络图</button></template>
      <template v-else><img class="mascot" :src="xiaoqi" alt="小岐"/><h1>这一招已经很稳了</h1><p>再补两处要点，就能从容过关。</p><div class="weak-list"><span v-for="point in store.result.weak_exam_point_ids" :key="point">{{ point }}</span><span v-if="!store.result.weak_exam_point_ids.length">回看病例中的辨证与禁忌</span></div><button class="remedy" @click="openRemediation">小岐带我补一补</button><button class="text-button" @click="restart">再试一次</button></template>
    </section>
    <section v-else-if="question" class="trial-stage">
      <div class="progress"><span v-for="gate in store.session?.gates" :key="gate.id" :class="{ active: gate.id === store.currentGate?.id }">{{ gate.name }}</span></div>
      <Transition name="question" mode="out-in"><article :key="question.id" ref="card" class="question-card" :class="{ ripple: correctFlash }">
        <button class="source-badge" :class="question.source_level" :title="sourceDetail(question)">{{ sourceLabel(question) }}</button>
        <div v-if="store.currentGate?.id === 'quick'" class="timer" :class="{ danger: remaining <= visual.timerWarningSeconds }"><svg viewBox="0 0 42 42"><circle class="track" cx="21" cy="21" r="18"/><circle class="count" cx="21" cy="21" r="18" :style="{ strokeDashoffset: 113 - 113 * remaining / Math.max(1, store.currentGate?.recommended_seconds || 1) }"/></svg><b>{{ remaining }}</b></div>
        <p class="gate-name">{{ store.currentGate?.name }}</p><h1>{{ question.stem }}</h1>
        <template v-if="store.currentGate?.id === 'case'"><div class="case-paper"><p v-for="(part, index) in caseParagraphs" v-show="caseStep >= index" :key="part">{{ part }}</p></div><p class="step-label">{{ ['辨证', '选药', '剂量与禁忌确认'][caseStep] }}</p></template>
        <div class="answers"><button v-for="option in question.options" :key="option.key" :class="{ selected: selected === option.key }" @click="selected = option.key"><b>{{ option.key }}</b>{{ option.text }}</button></div>
        <div class="card-foot"><span v-if="store.combo > 1" class="combo">combo ×{{ store.combo }}</span><button class="primary" :disabled="!selected || store.phase === 'transitioning'" @click="submit">{{ store.currentGate?.id === 'case' && caseStep < 2 ? '确认此步' : '拆招' }}</button></div>
      </article></Transition>
    </section>
    <el-dialog v-model="exitVisible" title="暂离试炼？" width="360px"><p>本关作答不会自动提交，返回后可重新开始。</p><template #footer><el-button @click="exitVisible = false">继续作答</el-button><el-button type="primary" @click="router.push('/path')">退出</el-button></template></el-dialog>
    <div v-if="store.error" class="retry"><span>{{ store.error }}</span><button @click="store.begin(nodeId)">再试一次</button></div>
  </main>
</template>
<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { gsap } from 'gsap'
import xiaoqi from '../assets/mascot/xiaoqi.png'
import { assessmentVisual as visual } from '../config/assessment'
import { useAssessmentStore } from '../stores/assessment'
import type { AssessmentQuestion } from '../types/assessment'
const route = useRoute(); const router = useRouter(); const store = useAssessmentStore(); const nodeId = computed(() => String(route.params.nodeId || 'herb_mahuang')); const nodeLabel = computed(() => String(route.query.label || '麻黄')); const question = computed(() => store.currentQuestion); const selected = ref(''); const remaining = ref(0); const caseStep = ref(0); const wrongFlash = ref(false); const correctFlash = ref(false); const exitVisible = ref(false); const seal = ref<HTMLElement>(); const card = ref<HTMLElement>(); const scoreDisplay = ref(0); let timer = 0
const caseParagraphs = ['患者初起恶寒发热，鼻塞无汗。', '继而咳喘，舌苔薄白，脉浮紧。', '请依次判断证候、选药，并确认剂量禁忌。']
const sourceLabel = (q: AssessmentQuestion) => q.source_level === 'real' ? `真题 · ${q.source_detail.year || ''}` : q.source_level === 'adapted' ? '改编' : 'AI原创'
const sourceDetail = (q: AssessmentQuestion) => Object.entries(q.source_detail).map(([k, v]) => `${k}: ${v}`).join('\n')
const resetTimer = () => { window.clearInterval(timer); remaining.value = store.currentGate?.recommended_seconds || 0; if (store.currentGate?.id === 'quick') timer = window.setInterval(() => { remaining.value -= 1; if (remaining.value <= 0) { window.clearInterval(timer); if (selected.value) void submit(); } }, 1000) }
const submit = async () => { if (!selected.value) return; if (store.currentGate?.id === 'case' && caseStep.value < 2) { caseStep.value += 1; return } const before = performance.now(); const grade = await store.submit(selected.value, Math.round((store.currentGate?.recommended_seconds || 0) - remaining.value + (performance.now() - before) / 1000)); if (!grade) return; if (grade.correct) { correctFlash.value = true; await nextTick(); if (card.value) gsap.fromTo(card.value, { boxShadow: '0 0 0 0 rgba(143,208,173,.65)' }, { boxShadow: '0 0 0 26px rgba(143,208,173,0)', duration: .46 }); window.setTimeout(() => correctFlash.value = false, 470) } else { wrongFlash.value = true; if (card.value) gsap.fromTo(card.value, { x: -5 }, { x: 5, duration: .045, repeat: 3, yoyo: true, clearProps: 'x' }); window.setTimeout(() => wrongFlash.value = false, visual.wrongFlashMs) } window.setTimeout(() => { selected.value = ''; caseStep.value = 0; store.next(); resetTimer() }, visual.quickTransitionMs) }
const requestExit = () => { exitVisible.value = true }; const returnToMap = () => router.push({ path: '/path', query: { [visual.passReturnQuery]: nodeId.value } }); const restart = () => void store.begin(nodeId.value); const openRemediation = () => router.push({ path: '/resources', query: { node_id: store.result?.remediation?.node_id || nodeId.value } })
watch(() => question.value?.id, () => resetTimer()); watch(() => store.result?.score, (score) => { if (score == null) return; gsap.to(scoreDisplay, { value: score, duration: .72, ease: 'power2.out', snap: { value: 1 } }); if (store.result?.passed) nextTick(() => { if (seal.value) gsap.fromTo(seal.value, { scale: 1.5, opacity: 0, filter: 'blur(4px)' }, { scale: 1, opacity: 1, filter: 'blur(0px)', duration: visual.sealMs / 1000, ease: 'back.out(2)' }) }) }); onMounted(() => void store.begin(nodeId.value)); onBeforeUnmount(() => window.clearInterval(timer))
</script>
<style scoped lang="scss">
.assessment-view{--coral:#c46a5d;min-height:100vh;padding:28px clamp(18px,5vw,80px);color:var(--qh-text);background:var(--qh-page-bg)}.assessment-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--qh-border);padding-bottom:18px}.assessment-head p,.gate-name{margin:0;color:var(--qh-color-gold);font-size:12px;font-weight:800;letter-spacing:1.2px}.assessment-head button{display:grid;width:34px;height:34px;place-items:center;border:1px solid var(--qh-border);border-radius:50%;color:var(--qh-text);background:transparent}.trial-stage{width:min(750px,100%);margin:40px auto}.progress{display:flex;justify-content:center;gap:20px;margin-bottom:20px;color:var(--qh-text-muted);font-size:12px}.progress .active{color:var(--qh-color-gold)}.question-card{position:relative;display:grid;gap:19px;min-height:440px;padding:clamp(24px,5vw,50px);border:1px solid rgba(143,208,173,.32);border-radius:8px;background:rgba(21,39,35,.78);overflow:hidden}.question-card.ripple:after{position:absolute;inset:0;border:1px solid var(--qh-color-jade);border-radius:inherit;content:'';animation:ripple .46s ease-out}.source-badge{position:absolute;top:18px;right:18px;padding:5px 8px;border-radius:3px;background:transparent;font-size:11px;cursor:help}.source-badge.real{border:0;color:#4a3615;background:var(--qh-color-gold)}.source-badge.adapted{border:1px solid var(--qh-color-jade);color:var(--qh-color-jade)}.source-badge.original{border:1px solid rgba(238,245,239,.55);color:var(--qh-text)}.timer{position:absolute;top:48px;right:20px;display:grid;width:50px;height:50px;place-items:center}.timer svg{position:absolute;width:100%;transform:rotate(-90deg)}.timer circle{fill:none;stroke-width:3}.track{stroke:rgba(238,245,239,.13)}.count{stroke:var(--qh-color-jade);stroke-dasharray:113;transition:stroke-dashoffset .8s linear}.timer b{font-size:12px}.timer.danger{color:var(--coral);animation:danger .7s ease-in-out infinite}.timer.danger .count{stroke:var(--coral)}h1{max-width:600px;margin:6px 0 0;font-family:var(--qh-font-display);font-size:clamp(24px,4vw,36px);line-height:1.35}.answers{display:grid;gap:10px}.answers button{display:flex;gap:12px;align-items:center;padding:13px 15px;border:1px solid rgba(143,208,173,.24);border-radius:5px;color:var(--qh-text);background:rgba(238,245,239,.025);text-align:left;font:inherit;cursor:pointer}.answers button:hover,.answers .selected{border-color:var(--qh-color-jade);background:rgba(143,208,173,.1)}.answers b{color:var(--qh-color-gold)}.card-foot{display:flex;justify-content:space-between;align-items:center;margin-top:auto}.primary,.remedy{padding:11px 19px;border:1px solid var(--qh-color-gold);border-radius:4px;color:#1a2923;background:var(--qh-color-gold);font-weight:900;cursor:pointer}.primary:disabled{opacity:.45}.combo{color:var(--qh-color-gold);font-family:var(--qh-font-display);font-size:14px;font-weight:900;animation:combo .25s ease-out}.case-paper{padding:17px 20px;border:1px solid rgba(116,94,60,.27);border-radius:3px;color:#354239;background:#f4ecd8;box-shadow:2px 3px 8px rgba(0,0,0,.18);background-image:radial-gradient(rgba(96,76,45,.18) .55px,transparent .6px);background-size:9px 9px}.case-paper p{margin:0;line-height:1.8}.case-paper p+p{margin-top:7px}.step-label{margin:0;color:var(--qh-color-gold);font-size:12px}.result-stage{display:grid;justify-items:center;align-content:center;min-height:calc(100vh - 90px);text-align:center}.score-wrap{position:relative;width:180px;height:180px;display:grid;place-items:center;align-content:center;border:2px solid var(--qh-color-jade);border-radius:50%;box-shadow:0 0 32px rgba(143,208,173,.18)}.score-wrap p,.score-wrap i{margin:0;color:var(--qh-text-muted);font-size:12px;font-style:normal}.score-wrap strong{font-family:var(--qh-font-display);font-size:64px;font-weight:900;line-height:1;animation:vp 1.6s ease-in-out infinite}.threshold{position:absolute;left:0;right:0;border-top:1px dashed var(--qh-color-gold);color:var(--qh-color-gold);font-size:10px}.pass-seal{display:grid;width:86px;height:86px;margin:25px 0 8px;place-items:center;border:4px double #c66d5d;border-radius:50%;color:#c66d5d;font-family:serif;font-size:52px;font-weight:900;transform:rotate(-8deg)}.mascot{width:88px;margin:24px 0 4px}.celebrate{animation:celebrate .42s ease-in-out 3}.result-stage>p{color:var(--qh-text-muted)}.weak-list{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;max-width:580px;margin:14px}.weak-list span{padding:7px 10px;border:1px solid rgba(231,194,116,.32);border-radius:3px;color:var(--qh-color-gold);font-size:12px}.text-button{margin-top:11px;border:0;color:var(--qh-text-muted);background:transparent}.retry{position:fixed;right:24px;bottom:24px;padding:12px;border:1px solid var(--qh-color-gold);background:#23352e}.retry button{margin-left:10px}.is-wrong .question-card{border-color:var(--coral)}.question-enter-active,.question-leave-active{transition:opacity .25s,transform .25s}.question-enter-from{opacity:0;transform:translateX(22px)}.question-leave-to{opacity:0;transform:translateX(-22px)}@keyframes ripple{from{opacity:.8;transform:scale(.96)}to{opacity:0;transform:scale(1.05)}}@keyframes danger{50%{transform:scale(1.08)}}@keyframes combo{from{transform:translateY(9px);opacity:0}to{transform:translateY(0)}}@keyframes celebrate{50%{transform:translateY(-13px)}}@media(max-width:560px){.assessment-view{padding:18px}.question-card{padding:24px}.timer{top:55px}.source-badge{right:14px}.answers button{font-size:14px}}
/* Stage 4 finish: restrained ink-and-jade motion language. */
.question-card { border-image: linear-gradient(115deg, var(--qh-color-jade), var(--qh-color-gold), var(--qh-color-jade-d)) 1; }
.timer.danger { animation-duration: var(--timer-danger-pulse, .72s); transform-origin: center; }
.combo { animation-duration: var(--combo-reveal, .22s); letter-spacing: .04em; }
.case-paper { border-color: var(--qh-color-paper-line); color: var(--qh-color-paper-ink); background: var(--qh-color-paper); background-image: radial-gradient(rgba(96,76,45,var(--paper-texture-opacity,.032)) .55px,transparent .6px), repeating-linear-gradient(0deg, transparent 0 25px, rgba(116,94,60,.07) 26px); box-shadow: var(--qh-shadow-scroll); }
.pass-seal { border-color: var(--qh-color-coral-deep); color: var(--qh-color-coral-deep); animation: seal-ink var(--seal-duration, .52s) cubic-bezier(.2,1.5,.35,1) both; }
@keyframes seal-ink { 0% { opacity:0; transform:scale(1.18) rotate(-8deg); filter:blur(5px); box-shadow:0 0 0 0 color-mix(in srgb,var(--qh-color-coral-deep) 35%,transparent); } 64% { opacity:1; transform:scale(.98) rotate(-8deg); filter:blur(0); } 100% { transform:scale(1) rotate(-8deg); box-shadow:0 0 0 18px transparent; } }
@media (prefers-reduced-motion: reduce) { .pass-seal,.timer.danger,.combo { animation: none; } }
</style>
